    marks = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    if not src or not marks:
        return g
    top = min(r for r, c in marks)
    bottom = max(r for r, c in src)
    for r, c in marks:
        g[r][c] = 0
    for r, c in src:
        rr = 2 * top - 1 - r
        if 0 <= rr < len(g):
            g[rr][c] = 4
    return g
