    for r, c in sixes:
        by_row.setdefault(r, []).append(c)
    longest_row = max(by_row, key=lambda r: len(by_row[r]))
    top, bottom = min(by_row), max(by_row)
    top_len, bottom_len = len(by_row[top]), len(by_row[bottom])
