    rows = {}
    for r, c in sixes:
        rows.setdefault(r, set()).add(c)
    widths = [len(v) for v in rows.values()]
    first_width = widths[0]
    last_width = widths[-1]
    top, bottom = min(rows), max(rows)
    if first_width > last_width:
        # T's bar is at the top: copy by horizontal reflection to the right.
        axis2 = 2 * max(c for r, c in fours) + 1
        for r, c in fours:
            cc = axis2 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    elif last_width > first_width:
        # T's bar is at the bottom: copy by horizontal reflection to the left.
        axis2 = 2 * min(c for r, c in fours) - 1
        for r, c in fours:
            cc = axis2 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        # Cross marker: vertically reflect to the side opposite the marker
        # when it cannot fit on the marker's side, otherwise toward it.
        source_top = min(r for r, c in fours)
        source_bottom = max(r for r, c in fours)
        marker_top, marker_bottom = min(r for r, c in sixes), max(r for r, c in sixes)
        below_fits = source_bottom + 1 + (source_bottom - source_top + 1) <= h
        if marker_bottom < source_top or (not below_fits and marker_bottom >= source_bottom):
            axis2 = 2 * source_top - 1
        else:
            axis2 = 2 * source_bottom + 1
        for r, c in fours:
            rr = axis2 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    return out

if __name__ == '__main__':
